# Expects a deal ID passed via payload params
deal_id = frappe.form_dict.get("deal_id")

if deal_id and frappe.db.exists("CRM Deal", deal_id):
    doc = frappe.get_doc("CRM Deal", deal_id)

    # 1. Resolve true Customer ID via the Organization link or fallbacks
    org_id = doc.get("organization")
    customer_id = None

    if org_id:
        customer_id = frappe.db.get_value("CRM Organization", org_id, "customer")
        if not customer_id and frappe.db.exists("Customer", org_id):
            customer_id = org_id

    if not customer_id:
        customer_id = doc.get("erpnext_customer") or doc.get("customer")

    # 2. Build the Document only if a customer relationship is established
    if customer_id:
        try:
            visit = frappe.new_doc("Maintenance Visit")
            visit.customer = customer_id
            visit.maintenance_type = "Scheduled"
            visit.completion_status = "Partially Completed"

            # Gather safe background metadata requirements
            user_company = frappe.defaults.get_user_default("company")
            global_company = frappe.db.get_value("Global Defaults", None, "default_company")
            visit.company = doc.get("company") or user_company or global_company

            visit.posting_date = frappe.utils.today()
            visit.posting_time = frappe.utils.nowtime()

            # 3. Pull line items defensively
            products_list = doc.get("products")
            if products_list:
                for item in products_list:
                    crm_p = item.get("product")
                    item_code = None

                    if crm_p:
                        if frappe.db.exists("Item", crm_p):
                            item_code = crm_p
                        else:
                            item_code = frappe.db.get_value("CRM Product", crm_p, "item_code")

                    if item_code:
                        visit.append("purposes", {
                            "item_code": item_code,
                            "item_name": item.get("product_name") or item.get("item_name") or item_code,
                            "description": item.get("description") or "Dispatched via CRM"
                        })

            # Structural fallback row
            if not visit.get("purposes"):
                visit.append("purposes", {
                    "description": "General maintenance services dispatched via CRM Deal"
                })

            # 4. Insert cleanly to database
            visit.insert(ignore_permissions=True)

        except Exception:
            frappe.log_error(title="Isolated Maintenance Visit Failure", message=frappe.get_traceback())

# Respond with a generic clean success dict so the background handler exits peacefully
frappe.response["message"] = "Processed"
